patch:
@@ -0,0 +1,1145 @@
+<!doctype html>
+<html lang="en">
+<head>
+<meta charset="utf-8">
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<title>Hive Mind OS Field Guide</title>
+<link rel="preconnect" href="https://fonts.googleapis.com">
+<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
+<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600&family=IBM+Plex+Sans:wght@400;500;600&family=IBM+Plex+Serif:wght@500;600;700&display=swap">
+
+<style>
+:root{
+  --ground:#E8EBF0; --surface:#FBFCFE; --surface-2:#F1F4F8;
+  --ink:#12161D; --ink-2:#4B5464; --ink-3:#7B8598;
+  --rule:#C6CEDA; --rule-soft:#DCE2EB;
+  --role-orchestrator:#5546C0; --role-explorer:#0B7A84; --role-architect:#215FA6;
+  --role-builder:#A2620A;      --role-curator:#9E2A45;  --role-integrator:#2A7A44;
+  --role-steward:#5A6930;      --role-optimizer:#8A3A8E;
+  --pass:#2A7A44; --fail:#9E2A45; --idle:#7B8598;
+  --shadow:0 1px 2px rgba(18,22,29,.06), 0 8px 24px -14px rgba(18,22,29,.30);
+  --measure:68ch;
+}
+@media (prefers-color-scheme: dark){
+  :root:not([data-theme="light"]){
+    --ground:#0D1015; --surface:#151920; --surface-2:#1B212A;
+    --ink:#E6EAF2; --ink-2:#A3ADBE; --ink-3:#6E7889;
+    --rule:#262C36; --rule-soft:#1F252E;
+    --role-orchestrator:#9A8DF2; --role-explorer:#3FC3D0; --role-architect:#6BA6EA;
+    --role-builder:#E2A34C;      --role-curator:#F27D93;  --role-integrator:#68C888;
+    --role-steward:#AABE60;      --role-optimizer:#D687DA;
+    --pass:#68C888; --fail:#F27D93; --idle:#6E7889;
+    --shadow:0 1px 2px rgba(0,0,0,.4), 0 10px 30px -18px rgba(0,0,0,.9);
+  }
+}
+:root[data-theme="dark"]{
+  --ground:#0D1015; --surface:#151920; --surface-2:#1B212A;
+  --ink:#E6EAF2; --ink-2:#A3ADBE; --ink-3:#6E7889;
+  --rule:#262C36; --rule-soft:#1F252E;
+  --role-orchestrator:#9A8DF2; --role-explorer:#3FC3D0; --role-architect:#6BA6EA;
+  --role-builder:#E2A34C;      --role-curator:#F27D93;  --role-integrator:#68C888;
+  --role-steward:#AABE60;      --role-optimizer:#D687DA;
+  --pass:#68C888; --fail:#F27D93; --idle:#6E7889;
+  --shadow:0 1px 2px rgba(0,0,0,.4), 0 10px 30px -18px rgba(0,0,0,.9);
+}
+
+*{box-sizing:border-box}
+body{
+  margin:0; background:var(--ground); color:var(--ink);
+  font-family:"IBM Plex Sans",-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
+  font-size:16px; line-height:1.62; -webkit-font-smoothing:antialiased;
+}
+.wrap{max-width:1180px; margin:0 auto; padding:0 24px 96px}
+p,li{color:var(--ink-2)}
+.measure{max-width:var(--measure)}
+a{color:var(--ink); text-decoration-color:var(--rule); text-underline-offset:3px}
+a:focus-visible,button:focus-visible{outline:2px solid var(--role-architect); outline-offset:3px; border-radius:2px}
+
+h1,h2,h3,h4{font-family:"IBM Plex Serif",Georgia,serif; color:var(--ink); text-wrap:balance; margin:0}
+h2{font-size:1.72rem; font-weight:600; line-height:1.22; letter-spacing:-.012em}
+h3{font-size:1.12rem; font-weight:600; line-height:1.3}
+h4{font-size:.98rem; font-weight:600}
+
+.eyebrow{
+  font-family:"IBM Plex Mono",ui-monospace,monospace; font-size:.68rem; font-weight:500;
+  letter-spacing:.16em; text-transform:uppercase; color:var(--ink-3);
+}
+code,.mono{font-family:"IBM Plex Mono",ui-monospace,SFMono-Regular,monospace}
+code{font-size:.86em; background:var(--surface-2); padding:.12em .38em; border-radius:3px; color:var(--ink)}
+pre{
+  font-family:"IBM Plex Mono",ui-monospace,monospace; font-size:.82rem; line-height:1.7;
+  background:var(--surface-2); border:1px solid var(--rule-soft); border-radius:6px;
+  padding:14px 16px; overflow-x:auto; margin:0; color:var(--ink);
+}
+pre .c{color:var(--ink-3)}
+
+/* ---- masthead ---- */
+.masthead{border-bottom:1px solid var(--rule); background:var(--surface)}
+.masthead .wrap{padding-top:40px; padding-bottom:34px; display:flex; flex-direction:column; gap:18px}
+.brandline{display:flex; align-items:baseline; gap:14px; flex-wrap:wrap}
+h1{font-size:2.5rem; font-weight:700; letter-spacing:-.022em; line-height:1.04}
+.vpill{
+  font-family:"IBM Plex Mono",monospace; font-size:.7rem; letter-spacing:.06em;
+  border:1px solid var(--rule); border-radius:99px; padding:3px 9px; color:var(--ink-3);
+}
+.thesis{font-size:1.14rem; line-height:1.55; max-width:60ch; color:var(--ink-2)}
+.thesis strong{color:var(--ink); font-weight:600}
+.masthead-meta{display:flex; gap:26px; flex-wrap:wrap; padding-top:6px; border-top:1px solid var(--rule-soft)}
+.mm{display:flex; flex-direction:column; gap:1px}
+.mm .k{font-family:"IBM Plex Mono",monospace; font-size:.66rem; letter-spacing:.14em; text-transform:uppercase; color:var(--ink-3)}
+.mm .v{font-size:.92rem; color:var(--ink); font-variant-numeric:tabular-nums}
+
+/* ---- sections ---- */
+section{padding-top:64px}
+.shead{display:flex; flex-direction:column; gap:8px; margin-bottom:26px}
+.shead p{margin:2px 0 0}
+
+/* ---- figures ---- */
+figure{margin:0; background:var(--surface); border:1px solid var(--rule); border-radius:8px; padding:22px 22px 16px; box-shadow:var(--shadow)}
+.figscroll{overflow-x:auto}
+.figscroll svg{min-width:860px}
+figure svg{display:block; width:100%; height:auto; color:var(--ink)}
+figcaption{margin-top:16px; padding-top:13px; border-top:1px solid var(--rule-soft); font-size:.86rem; line-height:1.55; color:var(--ink-2); max-width:82ch}
+figcaption b{color:var(--ink); font-weight:600}
+.svg-label{font-family:"IBM Plex Mono",monospace; font-size:11px; letter-spacing:.09em; text-transform:uppercase}
+.svg-title{font-family:"IBM Plex Sans",sans-serif; font-size:13.5px; font-weight:500}
+.svg-sub{font-family:"IBM Plex Mono",monospace; font-size:10px; letter-spacing:.02em}
+.svg-edge{font-family:"IBM Plex Mono",monospace; font-size:10px; letter-spacing:.05em}
+.svg-wave{font-family:"IBM Plex Mono",monospace; font-size:11.5px; letter-spacing:.14em; text-transform:uppercase}
+
+/* ---- role legend ---- */
+.legend{display:flex; flex-wrap:wrap; gap:7px; margin:0 0 24px}
+.chip{
+  display:inline-flex; align-items:center; gap:7px; font-family:"IBM Plex Mono",monospace;
+  font-size:.7rem; letter-spacing:.05em; padding:4px 10px 4px 8px; border-radius:99px;
+  border:1px solid var(--rule); background:var(--surface); color:var(--ink-2); white-space:nowrap;
+}
+.chip .dot{width:9px; height:9px; border-radius:2px; flex:none}
+.chip.planned .dot{background:transparent !important; border:1.5px dashed currentColor}
+.chip.planned{color:var(--ink-3)}
+
+/* ---- role cards ---- */
+.roles{display:grid; grid-template-columns:repeat(auto-fill,minmax(268px,1fr)); gap:14px}
+.role{
+  background:var(--surface); border:1px solid var(--rule); border-top:3px solid var(--rc);
+  border-radius:6px; padding:16px 17px 15px; display:flex; flex-direction:column; gap:9px;
+}
+.role.planned{border-top-style:dashed; background:transparent}
+.role-top{display:flex; align-items:baseline; justify-content:space-between; gap:10px}
+.role-name{font-family:"IBM Plex Mono",monospace; font-size:.76rem; font-weight:600; letter-spacing:.12em; text-transform:uppercase; color:var(--rc)}
+.role-state{font-family:"IBM Plex Mono",monospace; font-size:.62rem; letter-spacing:.1em; text-transform:uppercase; color:var(--ink-3)}
+.role p{margin:0; font-size:.88rem; line-height:1.5}
+.role dl{margin:0; display:flex; flex-direction:column; gap:7px; padding-top:3px; border-top:1px solid var(--rule-soft)}
+.role dt{font-family:"IBM Plex Mono",monospace; font-size:.6rem; letter-spacing:.13em; text-transform:uppercase; color:var(--ink-3); margin-bottom:2px}
+.role dd{margin:0; font-family:"IBM Plex Mono",monospace; font-size:.72rem; line-height:1.55; color:var(--ink-2)}
+
+/* ---- generic panels ---- */
+.panel{background:var(--surface); border:1px solid var(--rule); border-radius:8px; padding:20px 22px}
+.grid2{display:grid; grid-template-columns:repeat(auto-fit,minmax(320px,1fr)); gap:14px}
+.grid3{display:grid; grid-template-columns:repeat(auto-fit,minmax(300px,1fr)); gap:14px}
+
+/* ---- problem cards ---- */
+.problems{display:grid; grid-template-columns:repeat(auto-fit,minmax(330px,1fr)); gap:14px}
+.problem{background:var(--surface); border:1px solid var(--rule); border-radius:6px; padding:18px 19px; display:flex; flex-direction:column; gap:11px}
+.problem h3{font-size:1.04rem; line-height:1.32}
+.problem p{margin:0; font-size:.89rem; line-height:1.55}
+.problem pre{font-size:.76rem; padding:10px 12px; margin-top:auto}
+.rolerow{display:flex; gap:5px; flex-wrap:wrap}
+.rr{width:10px; height:10px; border-radius:2px; flex:none}
+.rr-wrap{display:flex; align-items:center; gap:8px; font-family:"IBM Plex Mono",monospace; font-size:.64rem; letter-spacing:.1em; text-transform:uppercase; color:var(--ink-3)}
+
+/* ---- tables ---- */
+.tablewrap{overflow-x:auto; border:1px solid var(--rule); border-radius:8px; background:var(--surface)}
+table{border-collapse:collapse; width:100%; font-size:.86rem; min-width:640px}
+th,td{text-align:left; padding:10px 14px; border-bottom:1px solid var(--rule-soft); vertical-align:top}
+thead th{
+  font-family:"IBM Plex Mono",monospace; font-size:.64rem; letter-spacing:.13em; text-transform:uppercase;
+  color:var(--ink-3); font-weight:500; background:var(--surface-2); border-bottom:1px solid var(--rule);
+}
+tbody tr:last-child td{border-bottom:none}
+td{color:var(--ink-2)}
+td.k{color:var(--ink); font-weight:500}
+td .mono{font-size:.8rem; color:var(--ink-2)}
+.tabnum{font-variant-numeric:tabular-nums}
+.state{font-family:"IBM Plex Mono",monospace; font-size:.68rem; letter-spacing:.08em; text-transform:uppercase; white-space:nowrap}
+.state.ok{color:var(--pass)} .state.no{color:var(--fail)} .state.na{color:var(--idle)}
+
+/* ---- callout ---- */
+.callout{border:1px solid var(--rule); border-left:3px solid var(--fail); background:var(--surface); border-radius:0 6px 6px 0; padding:16px 20px}
+.callout h4{margin-bottom:6px}
+.callout p{margin:0; font-size:.88rem}
+.callout ul{margin:8px 0 0; padding-left:18px; font-size:.85rem}
+
+/* ---- flow list ---- */
+ol.steps{counter-reset:s; list-style:none; margin:0; padding:0; display:flex; flex-direction:column; gap:12px}
+ol.steps li{counter-increment:s; display:grid; grid-template-columns:26px 1fr; gap:13px; font-size:.9rem; line-height:1.55}
+ol.steps li::before{
+  content:counter(s,decimal-leading-zero); font-family:"IBM Plex Mono",monospace; font-size:.68rem;
+  letter-spacing:.05em; color:var(--ink-3); padding-top:4px;
+}
+ol.steps b{color:var(--ink); font-weight:600}
+
+.foot{margin-top:72px; padding-top:22px; border-top:1px solid var(--rule); font-size:.82rem; color:var(--ink-3)}
+.foot p{margin:0 0 6px; font-size:.82rem; color:var(--ink-3)}
+
+@media (max-width:640px){
+  h1{font-size:1.95rem} h2{font-size:1.4rem}
+  .wrap{padding:0 16px 64px} section{padding-top:48px}
+  figure{padding:16px 14px 12px}
+}
+@media (prefers-reduced-motion:no-preference){
+  .role,.problem{transition:border-color .18s ease}
+}
+</style>
+</head>
+<body>
+<header class="masthead">
+  <div class="wrap">
+    <div class="brandline">
+      <h1>Hive Mind OS</h1>
+      <span class="vpill">v0.7.0 &middot; prototype</span>
+    </div>
+    <p class="thesis">Eight specialist agents do the work. A ninth thing &mdash; the evidence
+      layer &mdash; decides whether you should believe them. Every command, exit code, diff, and
+      verdict lands in a <strong>tamper-evident receipt bundle</strong> you can re-check
+      offline, long after the agent is gone.</p>
+    <div class="masthead-meta">
+      <div class="mm"><span class="k">Roles chartered</span><span class="v">8</span></div>
+      <div class="mm"><span class="k">Executing today</span><span class="v">3 &mdash; Explorer, Builder, Curator</span></div>
+      <div class="mm"><span class="k">Runtime deps</span><span class="v">0 &mdash; Python 3.11+ stdlib</span></div>
+      <div class="mm"><span class="k">Network required</span><span class="v">None</span></div>
+    </div>
+  </div>
+</header>
+
+<main class="wrap">
+
+<section id="gap">
+  <div class="shead">
+    <span class="eyebrow">The gap it fills</span>
+    <h2>CI runs after you decide to trust the change</h2>
+    <p class="measure">An agent framework orchestrates work and reports success. CI runs the tests
+      you already had, on a branch you already accepted into your pipeline. Neither one can tell
+      you what the agent <em>actually ran</em>, whether it quietly weakened a test, or whether the
+      check that passed was written before or after the code that had to pass it. Hive Mind OS
+      inserts a step between those two: an independent role that seals its checks first, then
+      re-runs them against the candidate in a workspace that has never seen the author's work.</p>
+  </div>
+
+  <figure class="figscroll">
+    <svg viewBox="0 0 1160 330" role="img" aria-label="One base commit is cloned three times. The Explorer reproduces the failure in its clone, the Curator writes and seals its checks against that same base, and the Builder writes the change in a third clone. Only then does the candidate cross the seal into the Curator's own workspace for an independent re-run.">
+      <defs>
+        <marker id="ar" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6.5" markerHeight="6.5" orient="auto-start-reverse">
+          <path d="M0,0 L10,5 L0,10 z" fill="currentColor"/>
+        </marker>
+        <marker id="ar-cur" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6.5" markerHeight="6.5" orient="auto-start-reverse">
+          <path d="M0,0 L10,5 L0,10 z" fill="var(--role-curator)"/>
+        </marker>
+      </defs>
+
+      <!-- source -->
+      <rect x="14" y="76" width="128" height="72" rx="4" fill="currentColor" fill-opacity=".05" stroke="currentColor" stroke-opacity=".38"/>
+      <text class="svg-label" x="28" y="100" fill="currentColor" fill-opacity=".55">your repo</text>
+      <text class="svg-title" x="28" y="120" fill="currentColor">base commit</text>
+      <text class="svg-sub" x="28" y="137" fill="currentColor" fill-opacity=".5">f1c725ed</text>
+
+      <!-- clone 1 and 2 -->
+      <path d="M142 112 H174 V50 H206" fill="none" stroke="currentColor" stroke-opacity=".45" marker-end="url(#ar)"/>
+      <path d="M142 112 H190 V128 H206" fill="none" stroke="currentColor" stroke-opacity=".45" marker-end="url(#ar)"/>
+      <text class="svg-edge" x="148" y="42" fill="currentColor" fill-opacity=".55">clone</text>
+      <text class="svg-edge" x="148" y="106" fill="currentColor" fill-opacity=".55">clone</text>
+
+      <!-- clone 3, routed under everything to the curator's own workspace -->
+      <path d="M142 112 H158 V296 H761 V264" fill="none" stroke="var(--role-curator)" stroke-opacity=".65" stroke-dasharray="5 4" marker-end="url(#ar-cur)"/>
+      <text class="svg-edge" x="300" y="290" fill="var(--role-curator)" fill-opacity=".85">clone 3 &mdash; the Curator's own workspace, made before any candidate exists</text>
+
+      <!-- explorer -->
+      <rect x="206" y="18" width="212" height="64" rx="4" fill="var(--role-explorer)" fill-opacity=".08" stroke="var(--role-explorer)"/>
+      <text class="svg-label" x="220" y="38" fill="var(--role-explorer)">explorer</text>
+      <text class="svg-title" x="220" y="57" fill="currentColor">Reproduce the failure</text>
+      <text class="svg-sub" x="220" y="73" fill="currentColor" fill-opacity=".55">read-only by role contract</text>
+
+      <!-- builder -->
+      <rect x="206" y="96" width="212" height="64" rx="4" fill="var(--role-builder)" fill-opacity=".09" stroke="var(--role-builder)"/>
+      <text class="svg-label" x="220" y="116" fill="var(--role-builder)">builder</text>
+      <text class="svg-title" x="220" y="135" fill="currentColor">Branch, edit, test, commit</text>
+      <text class="svg-sub" x="220" y="151" fill="currentColor" fill-opacity=".55">never pushes anywhere</text>
+
+      <!-- explorer's base feeds the seal -->
+      <path d="M418 50 H436 V232 H418" fill="none" stroke="var(--role-curator)" stroke-opacity=".7" marker-end="url(#ar-cur)"/>
+      <text class="svg-edge" x="444" y="70" fill="var(--role-curator)">seals against</text>
+      <text class="svg-edge" x="444" y="84" fill="var(--role-curator)">this base</text>
+
+      <!-- curator authoring -->
+      <rect x="206" y="200" width="212" height="64" rx="4" fill="var(--role-curator)" fill-opacity=".09" stroke="var(--role-curator)"/>
+      <text class="svg-label" x="220" y="220" fill="var(--role-curator)">curator</text>
+      <text class="svg-title" x="220" y="239" fill="currentColor">Write checks, then seal</text>
+      <text class="svg-sub" x="220" y="255" fill="currentColor" fill-opacity=".55">blind to the candidate</text>
+
+      <!-- seal line -->
+      <line x1="530" y1="32" x2="530" y2="272" stroke="var(--role-curator)" stroke-width="2" stroke-dasharray="7 5"/>
+      <text class="svg-label" x="530" y="24" fill="var(--role-curator)" text-anchor="middle">the seal</text>
+
+      <!-- candidate crosses -->
+      <path d="M418 128 H646" fill="none" stroke="currentColor" stroke-opacity=".5" marker-end="url(#ar)"/>
+      <rect x="459" y="109" width="146" height="15" fill="var(--surface)"/>
+      <text class="svg-edge" x="532" y="120" fill="currentColor" fill-opacity=".65" text-anchor="middle">candidate + 45 receipts</text>
+
+      <!-- sealed digest crosses -->
+      <path d="M418 232 H646" fill="none" stroke="var(--role-curator)" stroke-opacity=".8" marker-end="url(#ar-cur)"/>
+      <rect x="462" y="213" width="140" height="15" fill="var(--surface)"/>
+      <text class="svg-edge" x="532" y="224" fill="var(--role-curator)" text-anchor="middle">frozen digest 6d807427</text>
+
+      <!-- verification workspace -->
+      <rect x="646" y="96" width="230" height="168" rx="4" fill="var(--role-curator)" fill-opacity=".07" stroke="var(--role-curator)"/>
+      <text class="svg-label" x="660" y="118" fill="var(--role-curator)">curator workspace</text>
+      <text class="svg-title" x="660" y="140" fill="currentColor">Re-run the sealed checks</text>
+      <line x1="660" y1="152" x2="862" y2="152" stroke="var(--role-curator)" stroke-opacity=".3"/>
+      <text class="svg-sub" x="660" y="170" fill="currentColor" fill-opacity=".72">no builder rationale</text>
+      <text class="svg-sub" x="660" y="186" fill="currentColor" fill-opacity=".72">in its context window</text>
+      <text class="svg-sub" x="660" y="208" fill="currentColor" fill-opacity=".72">manifest checked for</text>
+      <text class="svg-sub" x="660" y="222" fill="currentColor" fill-opacity=".72">contamination first</text>
+      <text class="svg-sub" x="660" y="244" fill="currentColor" fill-opacity=".72">5-item checklist:</text>
+      <text class="svg-sub" x="660" y="258" fill="currentColor" fill-opacity=".72">pass / fail / not-evaluated</text>
+
+      <!-- verdict -->
+      <path d="M876 180 H916" fill="none" stroke="currentColor" stroke-opacity=".5" marker-end="url(#ar)"/>
+      <rect x="916" y="96" width="230" height="80" rx="4" fill="var(--pass)" fill-opacity=".1" stroke="var(--pass)"/>
+      <text class="svg-label" x="930" y="118" fill="var(--pass)">adopt</text>
+      <text class="svg-title" x="930" y="139" fill="currentColor">Bundle published</text>
+      <text class="svg-sub" x="930" y="156" fill="currentColor" fill-opacity=".6">patch, manifest, receipts,</text>
+      <text class="svg-sub" x="930" y="169" fill="currentColor" fill-opacity=".6">machine-readable report</text>
+
+      <path d="M876 180 H896 V226 H916" fill="none" stroke="currentColor" stroke-opacity=".3" stroke-dasharray="4 3" marker-end="url(#ar)"/>
+      <rect x="916" y="188" width="230" height="76" rx="4" fill="none" stroke="currentColor" stroke-opacity=".35" stroke-dasharray="5 4"/>
+      <text class="svg-label" x="930" y="210" fill="currentColor" fill-opacity=".55">reject</text>
+      <text class="svg-title" x="930" y="231" fill="currentColor" opacity=".8">Nothing is published</text>
+      <text class="svg-sub" x="930" y="248" fill="currentColor" fill-opacity=".55">failure evidence kept, but</text>
+      <text class="svg-sub" x="930" y="261" fill="currentColor" fill-opacity=".55">no bundle is ever written</text>
+    </svg>
+    <figcaption><b>One base commit, three isolated clones, one seal.</b> The Curator defines and
+      digests its acceptance checks against the <em>base</em> workspace and writes that digest to the
+      ledger &mdash; event 53 &mdash; before the Builder's candidate is ever handed over at event 66.
+      A check invented after seeing the patch cannot be smuggled in, because the digest would no
+      longer match. A failed verdict does not produce a bundle at all.</figcaption>
+  </figure>
+</section>
+
+<section id="run">
+  <div class="shead">
+    <span class="eyebrow">A real run, event by event</span>
+    <h2>The ledger is the product</h2>
+    <p class="measure">Below is the actual append-only ledger from <code>hive-mind demo</code>, run
+      on this machine. Ninety-seven events, each row hash-chained to the one before it, each
+      colored by the role that produced it. Forty-five of them are receipts: a command, its argv,
+      its exit code, and the digests of its stdout and stderr.</p>
+  </div>
