+        <tr><td class="k mono">WORK-010-profile</td><td><span class="state" style="color:var(--role-explorer)">explorer</span></td><td class="mono">R0</td><td class="mono">&mdash;</td><td>regression reproduced with a receipt</td><td class="mono">architect, curator</td></tr>
+        <tr><td class="k mono">WORK-011-survey</td><td><span class="state" style="color:var(--role-explorer)">explorer</span></td><td class="mono">R0</td><td class="mono">&mdash;</td><td>call graph enumerated</td><td class="mono">architect, curator</td></tr>
+        <tr><td class="k mono">WORK-020-design</td><td><span class="state" style="color:var(--role-architect)">architect</span></td><td class="mono">R1</td><td class="mono">&mdash;</td><td>ADR records rollback and threats</td><td class="mono">curator, steward</td></tr>
+        <tr><td class="k mono">WORK-030-cache</td><td><span class="state" style="color:var(--role-builder)">builder</span></td><td class="mono">R2</td><td class="mono">src/checkout/cache.py</td><td>sealed checks pass in the builder workspace</td><td class="mono">curator, architect</td></tr>
+        <tr><td class="k mono">WORK-031-index</td><td><span class="state" style="color:var(--role-builder)">builder</span></td><td class="mono">R3</td><td class="mono">migrations/0042_index.sql</td><td>migration is reversible &nbsp;<span class="state na">· human gate</span></td><td class="mono">curator, steward</td></tr>
+        <tr><td class="k mono">WORK-040-contract</td><td><span class="state" style="color:var(--role-integrator)">integrator</span></td><td class="mono">R1</td><td class="mono">src/checkout/api.py</td><td>public API contract unchanged</td><td class="mono">curator, architect</td></tr>
+        <tr><td class="k mono">WORK-050-health</td><td><span class="state" style="color:var(--role-steward)">steward</span></td><td class="mono">R1</td><td class="mono">docs/runbooks/cache.md</td><td>runbook and metric committed</td><td class="mono">curator, architect</td></tr>
+        <tr><td class="k mono">WORK-060-verify</td><td><span class="state" style="color:var(--role-curator)">curator</span></td><td class="mono">R2</td><td class="mono">&mdash;</td><td>verdict recorded from the sealed checks</td><td class="mono">architect, steward</td></tr>
